def derived_properties(grid):

    no = 0
    arr = [s.rstrip('0') if i % 2 == 1 else '0' + s.rstrip('1') for i, s in enumerate(grid)]
    for s in arr:
        if '1' in s:
            no += 1
    def reset(s):
        for i in range(s.index('0'), len(s)):
            if s[i] == '0':
                s = s[:i] + '000' + s[i + 3:]	
        return s

    while True:
        lis = [reset(s) for s in arr]
        arrNew = []
        for s in lis:
            arrNew.append(s)
            part = s.partition('1')
            x = part[0] + '1'
            y = part[1]
            z = s.index(part[2]) - 1
            if y and x[z] == '0':
                arrNew.append(x[:z] + '000' + x[z + 3:])
            if y == '1' and z > 0 and x[z - 1] == '0':
                arrNew.append(x[:z - 1] + '1' + x[z + 2:])
            if y == '1' and z < len(s) - 1 and s[z + 1] == '0':
                arrNew.append(x[:z + 4] + '1' + x[z + 4:])
            if y == '1' and z == len(s) - 1 and x[z - 1] == '0':
                arrNew.append(x[:z - 1] + '1' + x[-1])
        arr = arrNew
        if arr == lis: 
            break
    return no


