def find_neighbors(grid, x, y):
    neighbors = []
    if x > 0 and grid[x-1][y] == '1':
        neighbors.append((x-1, y))
    if x < len(grid) - 1 and grid[x+1][y] == '1':
        neighbors.append((x+1, y))
    if y > 0 and grid[x][y-1] == '1':
        neighbors.append((x, y-1))
    if y < len(grid[0]) - 1 and grid[x][y+1] == '1':
        neighbors.append((x, y+1))
    return neighbors

